#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

template <typename T>
class ScatterListKernel {
public:
    __aicore__ inline ScatterListKernel() {}

    __aicore__ inline void Init(GM_ADDR varRef, GM_ADDR indice, GM_ADDR updates, GM_ADDR mask,
                                int64_t numElements, int64_t axis,
                                int64_t reduceMode, int64_t dtypeSize,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailNum, int64_t tailLength,
                                int64_t tileLength);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t srcOffset, int64_t curTileLength);
    __aicore__ inline void CopyOut(int64_t dstOffset, int64_t curTileLength);

private:
    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;

    GlobalTensor<T> varRefGm;
    GlobalTensor<int64_t> indiceGm;
    GlobalTensor<T> updatesGm;
    GlobalTensor<int8_t> maskGm;

    int64_t numElements_ = 0;
    int64_t axis_ = 0;
    int64_t reduceMode_ = 0;
    int64_t dtypeSize_ = 2;
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailNum_ = 0;
    int64_t tailLength_ = 0;
