67	    updatesGm.SetGlobalBuffer((__gm__ T*)updates);
68	    maskGm.SetGlobalBuffer((__gm__ int8_t*)mask);
69	
70	    // 32 字节对齐
71	    constexpr int64_t alignNum = 32 / sizeof(T);
72	    int64_t alignedCopyLen = (maxCopyLen_ + alignNum - 1) / alignNum * alignNum;
73	    if (alignedCopyLen == 0) alignedCopyLen = alignNum;
74	
75	    // 可用 UB 空间
76	    int64_t availableUB = UB_CAPACITY;
77	    int64_t maxElementsInUB = availableUB / sizeof(T) / BUFFER_NUM;
78	
79	    if (alignedCopyLen > maxElementsInUB) {
80	        tileSize_ = maxElementsInUB / alignNum * alignNum;
81	        tileCount_ = (maxCopyLen_ + tileSize_ - 1) / tileSize_;
82	    } else {
