97	template <typename T>
98	__aicore__ inline void ScatterListKernel<T>::ProcessElement(int64_t elemIdx) {
99	    // 检查 mask
100	    int8_t maskVal = maskGm.GetValue(elemIdx);
101	    if (maskVal == 0) return;
102	
103	    // 读取 indice: [start, length]
104	    int64_t start = indiceGm.GetValue(elemIdx * 2);
105	    int64_t length = indiceGm.GetValue(elemIdx * 2 + 1);
106	
107	    if (length <= 0) return;
108	
109	    // 计算复制长度（取 min(length, maxCopyLen_)）
110	    int64_t copyLen = length < maxCopyLen_ ? length : maxCopyLen_;
111	
112	    // 获取 varRef 和 updates 的 GM 地址
113	    GlobalTensor<T> varRef = varRefGm[elemIdx];
114	
115	    // 计算偏移: 在 axis 轴上偏移 start
116	    // varRef 偏移 = start * innerSize
117	    // updates 偏移 = 0 * innerSize (从 updates[i] 的 axis 轴 0 开始)
118	    int64_t varRefOffset = start;
119	    int64_t updatesOffset = 0;
120	
121	    // 分 tile 处理
122	    int64_t remaining = copyLen;
123	    int64_t varRefPos = varRefOffset;
124	    int64_t updatesPos = updatesOffset;
125	
126	    while (remaining > 0) {
127	        int64_t curTileSize = tileSize_;
128	        if (curTileSize > remaining) {
129	            curTileSize = remaining;
130	        }
131	
132	        // CopyIn: updates → UB
133	        LocalTensor<T> srcLocal = inQueue.AllocTensor<T>();
134	        DataCopyExtParams copyParams;
135	        copyParams.blockCount = 1;
136	        copyParams.blockLen = static_cast<uint32_t>(curTileSize * sizeof(T));
137	        copyParams.srcStride = 0;
138	        copyParams.dstStride = 0;
139	        DataCopyPadExtParams<T> padParams;
140	        padParams.isPad = false;
141	
142	        DataCopyPad(srcLocal, updatesGm[updatesPos], copyParams, padParams);
143	        inQueue.EnQue<T>(srcLocal);
144	
145	        // CopyOut: UB → varRef
146	        LocalTensor<T> dstLocal = outQueue.AllocTensor<T>();
147	        LocalTensor<T> dataLocal = inQueue.DeQue<T>();
148	
149	        DataCopyPad(varRef[varRefPos], dataLocal, copyParams);
150	        outQueue.EnQue<T>(dstLocal);
151	
152	        LocalTensor<T> outLocal = outQueue.DeQue<T>();
153	        outQueue.FreeTensor(outLocal);
154	        inQueue.FreeTensor(dataLocal);
155	
156	        remaining -= curTileSize;
157	        varRefPos += curTileSize;
158	        updatesPos += curTileSize;
159	    }
