29	    TORCH_CHECK(indice.dim() == 2, "scatter_list: indice must be 2D");
30	    TORCH_CHECK(updates.dim() >= 2, "scatter_list: updates must be at least 2D");
31	    TORCH_CHECK(mask.dim() == 1, "scatter_list: mask must be 1D");
32	
33	    int64_t numElements = static_cast<int64_t>(varRef.size());
34	    TORCH_CHECK(numElements <= MAX_LIST_SIZE,
35	                "scatter_list: varRef list size ", numElements, " exceeds max ", MAX_LIST_SIZE);
36	
37	    // ---- 连续化 ----
38	    std::vector<at::Tensor> varRefContiguous;
39	    for (const auto& t : varRef) {
40	        varRefContiguous.push_back(t.contiguous());
41	    }
42	    at::Tensor indiceContiguous = indice.contiguous();
43	    at::Tensor updatesContiguous = updates.contiguous();
44	    at::Tensor maskContiguous = mask.contiguous();
45	
46	    // ---- 计算最大复制长度 ----
47	    int64_t maxCopyLen = 0;
48	    for (int64_t i = 0; i < numElements; i++) {
49	        int64_t start = indiceContiguous.index({i, 0}).item<int64_t>();
50	        int64_t length = indiceContiguous.index({i, 1}).item<int64_t>();
51	        if (maskContiguous.index({i}).item<bool>() && length > maxCopyLen) {
52	            maxCopyLen = length;
53	        }
54	    }
55	
56	    if (maxCopyLen == 0) {
57	        return varRefContiguous;
58	    }
59	
60	    // ---- 准备 GM 地址 ----
61	    // 由于 varRef 是列表，我们需要传递每个张量的地址
62	    // 最多支持 MAX_LIST_SIZE 个张量
63	    void* varRefAddrs[MAX_LIST_SIZE] = {nullptr};
64	    for (int64_t i = 0; i < numElements && i < MAX_LIST_SIZE; i++) {
65	        varRefAddrs[i] = varRefContiguous[i].data_ptr();
66	    }
67	
68	    // ---- Block 级 Tiling ----
69	    uint32_t blockDim = static_cast<uint32_t>(std::min(numElements, MAX_CORES));
70	    if (blockDim < 1) blockDim = 1;
71	
72	    int64_t totalLength = numElements * maxCopyLen;
73	
74	    // ---- 调用 Kernel ----
75	    // 注意: 由于 varRef 是列表，我们需要传递每个元素的地址
76	    // 这里简化处理，只传递前 MAX_LIST_SIZE 个地址
77	    void* varRef0 = varRefAddrs[0];
78	    void* varRef1 = (numElements > 1) ? varRefAddrs[1] : varRefAddrs[0];
79	    void* varRef2 = (numElements > 2) ? varRefAddrs[2] : varRefAddrs[0];
80	
81	    int64_t numElementsVal = numElements;
82	    int64_t axisVal = axis;
83	    int64_t totalLengthVal = totalLength;
84	    int64_t maxCopyLenVal = maxCopyLen;
85	
86	    EXEC_KERNEL_CMD(scatter_list, blockDim,
