#include "torch_kernel_helper.h"
#include "aclrtlaunch_scatter_list.h"
#include <torch/extension.h>
#include <vector>

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;

at::Tensor scatter_list(const at::TensorList &varRef,
                        const at::Tensor &indice,
                        const at::Tensor &updates,
                        const at::Tensor &mask,
                        int64_t reduce,
                        int64_t axis) {
    // ---- 输入校验 ----
    TORCH_CHECK(!varRef.empty(), "scatter_list: varRef must not be empty");
    TORCH_CHECK(indice.dim() == 2, "scatter_list: indice must be 2D");
    TORCH_CHECK(indice.size(1) == 2, "scatter_list: indice must have shape [N, 2]");
    TORCH_CHECK(updates.dim() >= 2, "scatter_list: updates must be at least 2D");
    TORCH_CHECK(mask.dim() == 1, "scatter_list: mask must be 1D");

    int64_t numElements = static_cast<int64_t>(varRef.size());
    TORCH_CHECK(indice.size(0) == numElements,
                "scatter_list: indice size ", indice.size(0), " != varRef size ", numElements);
    TORCH_CHECK(updates.size(0) == numElements,
                "scatter_list: updates size ", updates.size(0), " != varRef size ", numElements);
    TORCH_CHECK(mask.size(0) == numElements,
                "scatter_list: mask size ", mask.size(0), " != varRef size ", numElements);

    // ---- 连续化 ----
    std::vector<at::Tensor> varRefContiguous;
    for (const auto& t : varRef) {
        varRefContiguous.push_back(t.contiguous());
    }
    at::Tensor indiceContiguous = indice.contiguous();
    at::Tensor updatesContiguous = updates.contiguous();
    at::Tensor maskContiguous = mask.contiguous();

    // ---- 获取数据类型信息 ----
    int64_t dtypeSize = varRefContiguous[0].element_size();
    auto dtype = varRefContiguous[0].scalar_type();

    // ---- axis 归一化 ----
    int64_t ndim = varRefContiguous[0].dim();
    if (axis < 0) axis += ndim;
    TORCH_CHECK(axis >= 0 && axis < ndim, "scatter_list: axis out of range");

    // ---- 计算每个元素的 outerSize 和 innerSize ----
    int64_t outerSize = 1;
    for (int64_t i = 0; i < axis; i++) {
        outerSize *= varRefContiguous[0].size(i);
    }
    int64_t innerSize = 1;
    for (int64_t i = axis + 1; i < ndim; i++) {
        innerSize *= varRefContiguous[0].size(i);
    }

    // ---- 展平 varRef 和 updates ----
    // 将每个 varRef[i] 和 updates[i] 展平为 1D，然后拼接
    std::vector<at::Tensor> varRefFlat;
    std::vector<at::Tensor> updatesFlat;
    int64_t maxCopyLen = 0;

    for (int64_t i = 0; i < numElements; i++) {
        // 展平 varRef[i]
        auto vflat = varRefContiguous[i].reshape({-1});
        varRefFlat.push_back(vflat);

        // 展平 updates[i]
        auto uflat = updatesContiguous[i].reshape({-1});
        updatesFlat.push_back(uflat);

        // 获取 indice
        int64_t start = indiceContiguous.index({i, 0}).item<int64_t>();
        int64_t length = indiceContiguous.index({i, 1}).item<int64_t>();

        if (maskContiguous.index({i}).item<bool>() && length > maxCopyLen) {
            maxCopyLen = length;
        }
    }

    // 拼接所有展平后的张量
    at::Tensor varRefConcat = at::cat(varRefFlat, 0);
    at::Tensor updatesConcat = at::cat(updatesFlat, 0);

    // ---- mask 转 int8 ----
    at::Tensor maskInt8 = maskContiguous.to(at::kChar);

    // ---- Block 级 Tiling ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    int64_t totalLength = numElements * maxCopyLen;
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t CACHE_LINE = 512;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE - 1) / CACHE_LINE * CACHE_LINE;
    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;

    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailNum = 1;
    int64_t tailLength = totalLength - (usedCoreNum - 1) * formerLength;
    if (tailLength < 0) tailLength = 0;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    if (blockDim < 1) blockDim = 1;

    // ---- UB 级 Tiling ----
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t bufferCoefficient = (dtypeSize == 4) ? 16 : 8;
    int64_t alignElements = 32 / dtypeSize;
    int64_t maxTileElements = static_cast<int64_t>(ubSize) / bufferCoefficient;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < alignElements) tileLength = alignElements;

    // ---- 调用 Kernel ----
    int64_t numElementsVal = numElements;
    int64_t axisVal = axis;
    int64_t reduceVal = reduce;
    int64_t dtypeSizeVal = dtypeSize;
    int64_t formerNumVal = formerNum;
    int64_t formerLengthVal = formerLength;
    int64_t tailNumVal = tailNum;
    int64_t tailLengthVal = tailLength;
    int64_t tileLengthVal = tileLength;

    EXEC_KERNEL_CMD(scatter_list, blockDim,
                    varRefConcat, indiceContiguous, updatesConcat, maskInt8,
                    numElementsVal, axisVal, reduceVal, dtypeSizeVal,
                    formerNumVal, formerLengthVal, tailNumVal, tailLengthVal, tileLengthVal);

    // 将更新后的数据复制回原始 varRef
    int64_t offset = 0;
    for (int64_t i = 0; i < numElements; i++) {
        int64_t elemSize = varRefContiguous[i].numel();
        varRefContiguous[i].copy_(varRefConcat.narrow(0, offset, elemSize).reshape(varRefContiguous[i].sizes()));
        offset += elemSize;
    }

    // 返回第一个元素作为输出（与 PyTorch 参考实现一致）
    return varRefContiguous[0];
}

}  // namespace ascend_kernel
